# Check more markers for macrophage subtypes and tumor cells
additional_markers = {
    'M2 Macrophage': ['CD163', 'STAB1', 'FCGBP', 'MRC1', 'CD206'],
    'Tumor cell': ['GFAP', 'SOX2', 'VIM', 'MGMT', 'EGFR', 'IDH1'],
    'Inflammatory': ['CXCL8', 'IL1B', 'TNF', 'IL6']
}

all_markers = []
for cluster in ['0', '3', '12', '18']:
    genes = list(adata.uns['rank_genes_groups']['names'][cluster])
    all_markers.append(genes)

print("Additional marker presence in top 20 genes per cluster:")
for cell_type, markers in additional_markers.items():
    print(f"\n{cell_type}:")
    for i, cluster in enumerate(['0', '3', '12', '18']):
        top_genes = all_markers[i]
        found = [g for g in markers if g in top_genes]
        if found:
            print(f"  Cluster {cluster}: {found}")

# Also check if VIM is in cluster 12 or 18 (glioblastoma cells often express vimentin)
print("\n\nVIM (vimentin) check:")
for i, cluster in enumerate(['0', '3', '12', '18']):
    if 'VIM' in all_markers[i]:
        print(f"  VIM found in Cluster {cluster} top 20")
